window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f95178a0c81b52b6"]={"versions": [{"id": "FIG-f95178a0c81b52b6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines Protokoll-Datenpakets (N-PDU / Frame-Format). Das Diagramm spezifiziert die interne Feldstruktur des First Frame Extended (FF Extended) innerhalb des AUTOSAR FlexRay Transport Layer (FrArTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format gliedert sich in Protokollsteuerungs- und Nutzdatenabschnitte:</p>\n<ul class=\"fig-list\"><li><strong>PCI (Protocol Control Information)</strong>: Umfasst insgesamt 5 Byte (40 Bit), unterteilt in:\n<ul class=\"fig-list\"><li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des Frame-Typs (First Frame).\n</li><li><strong>Res (Reserved)</strong>: 4 Bit reservierter Bereich.\n</li><li><strong>DL (Data Length)</strong>: 32 Bit langes Feld zur Codierung der Gesamtlänge der zu übertragenden Botschaft im erweiterten Adressierungs-/Längenformat.\n</li></ul>\n</li><li><strong>Data (Payload)</strong>: Folgt unmittelbar auf die PCI mit variabler Länge (abhängig von der PDU- bzw. Cluster-Konfiguration).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim segmentierten Senden einer Botschaft, deren Gesamtlänge den Standard-Längenbereich übersteigt, leitet der FrArTp die Übertragung mit einem First Frame Extended ein. Der Sender belegt FT mit dem Typbezeichner für First Frame und trägt die vollständige Nutzlänge (bis zu 32 Bit adressierbar) in das Feld DL ein. Die ersten Nutzdatenbytes werden direkt im nachfolgenden Feld Data mitgeführt. Der Empfänger wertet FT und DL aus, allokiert die entsprechenden Pufferressourcen und erwartet die nachfolgenden Consecutive Frames (CF).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Frame-Layout für Implementierungen des AUTOSAR FrArTp-Moduls bei Verwendung der erweiterten Längenadressierung (Extended Data Length). Die 5 Byte PCI müssen byte- und bitexakt gemäß der definierten Reihenfolge (FT, Res, DL) serialisiert werden. Entwickler müssen sicherstellen, dass das Feld Res ungenutzt bzw. spezifikationskonform maskiert bleibt und die PDU-Puffer mindestens 5 Byte PCI plus konfigurierte Nutzdaten aufnehmen können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4cd19238e39dd51c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines Protokoll-Datenpakets (N-PDU / Frame-Format). Das Diagramm spezifiziert die interne Feldstruktur des First Frame Extended (FF Extended) innerhalb des AUTOSAR FlexRay Transport Layer (FrArTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format gliedert sich in Protokollsteuerungs- und Nutzdatenabschnitte:</p>\n<ul class=\"fig-list\"><li><strong>PCI (Protocol Control Information)</strong>: Umfasst insgesamt 5 Byte (40 Bit), unterteilt in:\n<ul class=\"fig-list\"><li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des Frame-Typs (First Frame).\n</li><li><strong>Res (Reserved)</strong>: 4 Bit reservierter Bereich.\n</li><li><strong>DL (Data Length)</strong>: 32 Bit langes Feld zur Codierung der Gesamtlänge der zu übertragenden Botschaft im erweiterten Adressierungs-/Längenformat.\n</li></ul>\n</li><li><strong>Data (Payload)</strong>: Folgt unmittelbar auf die PCI mit variabler Länge (abhängig von der PDU- bzw. Cluster-Konfiguration).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim segmentierten Senden einer Botschaft, deren Gesamtlänge den Standard-Längenbereich übersteigt, leitet der FrArTp die Übertragung mit einem First Frame Extended ein. Der Sender belegt FT mit dem Typbezeichner für First Frame und trägt die vollständige Nutzlänge (bis zu 32 Bit adressierbar) in das Feld DL ein. Die ersten Nutzdatenbytes werden direkt im nachfolgenden Feld Data mitgeführt. Der Empfänger wertet FT und DL aus, allokiert die entsprechenden Pufferressourcen und erwartet die nachfolgenden Consecutive Frames (CF).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Frame-Layout für Implementierungen des AUTOSAR FrArTp-Moduls bei Verwendung der erweiterten Längenadressierung (Extended Data Length). Die 5 Byte PCI müssen byte- und bitexakt gemäß der definierten Reihenfolge (FT, Res, DL) serialisiert werden. Entwickler müssen sicherstellen, dass das Feld Res ungenutzt bzw. spezifikationskonform maskiert bleibt und die PDU-Puffer mindestens 5 Byte PCI plus konfigurierte Nutzdaten aufnehmen können.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f95178a0c81b52b6", "to": "FIG-4cd19238e39dd51c", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
